//! nn layer numerics vs tinygrad goldens: the norm family (InstanceNorm,
//! LayerNorm2d, RMSNorm), Embedding/LSTMCell, and the conv variants.
//!
//! `tests/nn_golden.rs` is generated by `py/dump_nn_golden.py`.

use autorust::engine::session::Session;
use autorust::tensor::nn::{
    ConvTranspose2d, Embedding, InstanceNorm, LSTMCell, LayerNorm2d, RMSNorm, conv_transpose1d,
    conv1d,
};
use autorust::tensor::{Ctx, Tensor};

mod nn_golden;
use nn_golden::{C1D_GOLDEN, CT_GOLDEN, EMB_GOLDEN, IN_GOLDEN, L2_GOLDEN, LSTM_GOLDEN, RMS_GOLDEN};

fn close(got: &[f32], want: &[f32], rtol: f32, name: &str) {
    assert_eq!(
        got.len(),
        want.len(),
        "{name}: length {} != {}",
        got.len(),
        want.len()
    );
    for (i, (a, b)) in got.iter().zip(want.iter()).enumerate() {
        let tol = rtol * b.abs().max(1.0);
        assert!(
            (a - b).abs() <= tol,
            "{name}[{i}]: got {a}, want {b} (diff {}, tol {tol})",
            (a - b).abs()
        );
    }
}

fn shape_of(t: &Tensor) -> Vec<usize> {
    t.shape()
        .as_slice()
        .iter()
        .map(|s| s.clone().as_i64().unwrap_or(0) as usize)
        .collect()
}

#[test]
fn instancenorm_matches_tinygrad() {
    for g in IN_GOLDEN {
        let ctx = Ctx::new();
        let mut sess = Session::new();
        let x = Tensor::from_slice(&ctx, g.x, None, None).reshape(g.x_shape);
        let mut m = InstanceNorm::new(&ctx, g.num_features, g.eps, true);
        m.weight = Some(Tensor::from_slice(&ctx, g.weight, None, None));
        m.bias = Some(Tensor::from_slice(&ctx, g.bias, None, None));
        let out = m.forward(&x);
        assert_eq!(shape_of(&out), g.out_shape.to_vec(), "{}: shape", g.name);
        close(&out.to_list::<f32>(&mut sess), g.out, 1e-4, g.name);
    }
}

#[test]
fn layernorm2d_matches_tinygrad() {
    for g in L2_GOLDEN {
        let ctx = Ctx::new();
        let mut sess = Session::new();
        let x = Tensor::from_slice(&ctx, g.x, None, None).reshape(g.x_shape);
        let mut m = LayerNorm2d::new(&ctx, g.num_channels, g.eps, true);
        m.norm.weight = Some(Tensor::from_slice(&ctx, g.weight, None, None));
        m.norm.bias = Some(Tensor::from_slice(&ctx, g.bias, None, None));
        let out = m.forward(&x);
        assert_eq!(shape_of(&out), g.out_shape.to_vec(), "{}: shape", g.name);
        close(&out.to_list::<f32>(&mut sess), g.out, 1e-4, g.name);
    }
}

